        { id: "l14k2", type: "count", front: "مجلسا البرلمان السويسري (الجمعية الاتحادية الفيدرالية)", n: 2, lead: "يتكون من مجلسين:", items: ["المجلس الوطني", "مجلس المقاطعات"], pg: "94–95" },
        { id: "l14k3", type: "def", front: "ما اسم الهيئة التي يشكلها البرلمان السويسري لتقوم بوظيفة الحكومة؟", back: "المجلس الاتحادي الفيدرالي", bk: true, pg: "94–95" },
        { id: "l14k4", type: "count", front: "خصائص النظام المجلسي (حكومة الجمعية النيابية)", n: 2, lead: "خاصيتان:", items: ["تركيز السلطة بيد البرلمان (الجمعية الاتحادية الفيدرالية)", "الدمج بين السلطتين التشريعية والتنفيذية مع تبعية التنفيذية للتشريعية"], pg: "95" },
        { id: "l14k5", type: "rule", front: "سلطة البرلمان على الحكومة في النظام المجلسي", rule: "يتولى البرلمان كل السلطات، بما في ذلك تعيين أعضاء الحكومة وعزلهم، ومخالفة قراراتها أو إلغاؤها عند الضرورة.", exc: "وفي المقابل لا تملك الحكومة أية حقوق دستورية تجاه البرلمان كالتي في البرلماني: لا حق الحل، ولا دعوته للانعقاد، ولا تأجيل اجتماعاته.", pg: "95" },
        { id: "l14k6", type: "rule", front: "طبيعة العلاقة بين السلطتين في النظام المجلسي", rule: "دمج بين التشريعية والتنفيذية، فتبدوان وكأنهما سلطة واحدة، مع تبعية التنفيذية للتشريعية.", exc: "وليس الفصل كما في الرئاسي، ولا التعاون والمساواة كما في البرلماني.", pg: "95" },
        { id: "l14k7", type: "def", front: "ما الذي يثير التساؤل حول ديمقراطية النظام المجلسي، وما من عيوبه؟", back: "تركيز السلطات أو دمجها في هيئة واحدة يثير مخاوف من الاستبداد أو الاستئثار بالسلطة؛ ومن عيوبه إضعاف السلطة التنفيذية وعجزها عن التعامل مع المخاطر في الوقت المناسب وبالقدرة اللازمة.", bk: false, pg: "95" },
        { id: "l14k8", type: "count", front: "الدولتان اللتان أفرز فيهما النظام المجلسي حكومات غير ديمقراطية", n: 2, lead: "خارج موطنه الأصلي:", items: ["فرنسا: أخذت به في أعقاب ثورتها ثم تخلت عنه ثم عادت إليه ثم تركته", "تركيا: في أحد دساتيرها"], pg: "95–96" },
        { id: "l14k9", type: "rule", front: "نجاح النظام المجلسي", rule: "أثبت نجاحه واستمراره في سويسرا، لارتفاع درجة النضج والوعي الشعبي والاستقرار السياسي.", exc: "لكنه ظل حصراً على التجربة السويسرية، وصعب استنساخه في بيئات أجنبية أخرى.", pg: "95–96" }
