  tables: [
    { id: "c4t1", title: "القانون الدستوري والنظام السياسي", cols: ["وجه المقارنة", "القانون الدستوري", "النظام السياسي"], rows: [
      ["المضمون", "قواعد قانونية تبين شكل الدولة والحكومة والسلطات العامة والعلاقة بينها والحقوق والواجبات", "يتجاوز الإطار القانوني إلى أمور اقتصادية واجتماعية وسياسية وأيديولوجية وثقافية"],
      ["النطاق", "أقل شمولاً", "أشمل"],
      ["زاوية الدراسة", "الجانب القانوني", "الناحية السياسية"]
    ], core: "كلاهما يتناول نظام الحكم والسلطات الثلاث والحقوق والواجبات، لكن النظام السياسي أشمل ويُدرس من الناحية السياسية، والقانون الدستوري من الجانب القانوني.", pg: "87" },
    { id: "c4t2", title: "الفصل بين السلطات والتعاون بينها", cols: ["وجه المقارنة", "الفصل بين السلطات", "التعاون بين السلطات"], rows: [
      ["المضمون", "عدم تركيز السلطة في هيئة واحدة، وتوليها هيئات مستقلة", "قنوات تواصل وأوجه تعاون تنص عليها الدساتير"],
      ["المنشأ", "رؤية جون لوك ومونتسكيو لمنع استئثار أي سلطة بالسلطة", "ثبوت استحالة الفصل التام بالتجربة العملية"],
      ["عند الأمريكيين", "فُسّر عند صياغة الدستور الاتحادي بالفصل المطلق", "تحول تدريجي إلى الفصل النسبي دون المساس بالدستور"],
      ["عند الفرنسيين", "تحمس له الثوار في البداية", "توصلوا إليه بعد مضي عدة سنوات على ثورتهم"],
      ["قيمته", "أداة فعالة لتقييد السلطة: السلطة تحد السلطة", "مطلب تقتضيه ضرورات العمل السياسي"],
      ["ما يميز الأنظمة", "ماهية الفصل ودرجته", "درجة التعاون وماهيته"]
    ], core: "الفصل لا يعني الاستقلال التام والتعاون ضرورة، وما يميز نظاماً من آخر درجة كل منهما وماهيته.", pg: "88–92" },
    { id: "c4t3", title: "الأنظمة الأربعة: البرلماني والمجلسي والرئاسي والمختلط", cols: ["وجه المقارنة", "البرلماني", "المجلسي", "الرئاسي", "المختلط"], rows: [
      ["الموطن أو التطبيق", "بريطانيا منشؤه الأصلي", "سويسرا", "التجربة الأمريكية", "طُبق في فرنسا (ديجول) وإسبانيا وفنلندا وإيرلندا"],
      ["العلاقة بين السلطتين", "فصل مرن مع تعاون وتوازن", "دمج مع تبعية التنفيذية للتشريعية", "فصل شبه تام: استقلال عضوي ووظيفي", "يقتبس من البرلماني والرئاسي دون المجلسي"],
      ["السلطة التنفيذية", "ثنائية: رئيس دولة يسود ولا يحكم، ورئيس وزراء", "هيئة يشكلها البرلمان (المجلس الاتحادي الفيدرالي)", "يستأثر بها رئيس الجمهورية", "ثنائية: رئيس دولة منتخب مباشرة، ورئيس حكومة"],
      ["حق الحل", "للحكومة حل البرلمان", "لا تملكه الحكومة", "لا يملك الرئيس حل الكونجرس", "حق حل البرلمان في مقابل مسؤولية الوزارة"],
      ["المسؤولية أمام البرلمان", "الوزارة مسؤولة تضامنياً، ورئيس الدولة غير مسؤول", "البرلمان يعين أعضاء الحكومة ويعزلهم", "مساءلة لا تؤدي إلى سحب الثقة", "الوزارة مسؤولة سياسياً، والرئيس غير مسؤول عن اختصاصاته المستقلة"],
      ["الانتشار والنجاح", "الأكثر انتشاراً؛ نجح في دول وأخفق في أخرى", "نجح في سويسرا وحدها، وأخفق في فرنسا وتركيا", "محدود خارج موطنه؛ أخفق في بعض دول أمريكا الجنوبية", "فشل في مصر واليمن وسوريا، ثم تبنته دول ديمقراطية على أسس صحيحة"]
    ], core: "يتميز كل نظام بعلاقة التشريعية بالتنفيذية: فصل مرن وتعاون في البرلماني، ودمج وتبعية في المجلسي، وفصل شبه تام في الرئاسي، ومزيج من البرلماني والرئاسي في المختلط.", pg: "92–101" },
    { id: "c4t4", title: "ما يقتبسه النظام المختلط من البرلماني ومن الرئاسي", cols: ["وجه المقارنة", "المقتبس من البرلماني", "المقتبس من الرئاسي"], rows: [
      ["المضمون", "ثنائية السلطة التنفيذية، ومسؤولية الوزارة سياسياً أمام البرلمان", "اختصاصات خاصة ومستقلة لرئيس الدولة دون موافقة الوزارة"],
      ["أثره في المسؤولية", "البرلمان قادر، دستورياً على الأقل، على إسقاط الوزارة إذا فقدت الثقة", "رئيس الدولة غير مسؤول أمام البرلمان عن هذه الاختصاصات"],
      ["ما يقابله أو يعلّله", "حق حل البرلمان في مقابل المسؤولية", "توليه منصبه بالاقتراع المباشر لا عن طريق البرلمان"],
      ["عدد المقتبس", "أمران", "أمر واحد"]
    ], core: "يأخذ المختلط من البرلماني ثنائية التنفيذ ومسؤولية الوزارة مع حق الحل، ومن الرئاسي استقلال رئيس الدولة المنتخب مباشرة باختصاصات لا يُسأل عنها، ولا يأخذ من المجلسي شيئاً.", pg: "99–100" }
  ],
